package dockerapp

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"syscall"
	"time"
)

// GuardCheck is also used by the legacy start operation. Missing registration
// is handled by its caller, never interpreted here as permission to fall back.
func GuardCheck(ctx context.Context, store Store, native Native) error {
	state, raw, err := store.Load()
	if err != nil {
		return err
	}
	if len(raw) == 0 {
		return errors.New("DOCKER_GUARD_REGISTRATION_MISSING")
	}
	if state.Phase != "active" && state.Phase != "starting" {
		return errors.New("DOCKER_MIGRATION_INCOMPLETE: 查看原迁移任务，禁止自动启动")
	}
	_, path, err := native.config(ctx)
	if err != nil {
		return err
	}
	if path != state.Parameters.Target.Path {
		return errors.New("DOCKER_DATA_ROOT_CHANGED")
	}
	_, err = native.Check(ctx, state.Parameters.Target, false)
	return err
}

// GuardExec accepts only the two native dockerd init forms. It checks generated
// daemon.json too: alternate configuration cannot select a different data-root.
func GuardExec(args []string) error {
	config := ""
	if len(args) == 1 && args[0] == "--config-file=/tmp/dockerd/daemon.json" {
		config = "/tmp/dockerd/daemon.json"
	} else if len(args) != 0 {
		return errors.New("DOCKER_GUARD_ARGUMENTS_INVALID")
	}
	if config == "" {
		return errors.New("DOCKER_CONFIG_REQUIRED")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	reader := newNativeReader()
	native := Native{Reader: reader}
	store := Store{Path: StatePath}
	var last error
	for {
		last = GuardReady(ctx, store, native)
		if last == nil {
			break
		}
		select {
		case <-ctx.Done():
			return last
		case <-time.After(time.Second):
		}
	}
	state, _, err := store.Load()
	if err != nil {
		return err
	}
	raw, err := os.ReadFile(config)
	if err != nil || len(raw) > 256*1024 {
		return errors.New("DOCKER_DAEMON_CONFIG_UNREADABLE")
	}
	var actual struct {
		Root string `json:"data-root"`
		Live bool   `json:"live-restore"`
	}
	if json.Unmarshal(raw, &actual) != nil || actual.Root != state.Parameters.Target.Path || actual.Live {
		return errors.New("DOCKER_DAEMON_CONFIG_MISMATCH")
	}
	return syscall.Exec("/usr/bin/dockerd", append([]string{"/usr/bin/dockerd"}, args...), []string{"PATH=/usr/sbin:/usr/bin:/sbin:/bin", "HOME=/root"})
}

